/**
 * A queue that runs the jobs it is given one after another, each starting when
 * the one before has finished, whether that one succeeded or not. Every job
 * gets its own result (or its own rejection).
 */
export const serial = (): (<T>(job: () => Promise<T>) => Promise<T>) => {
  let tail: Promise<unknown> = Promise.resolve()

  return job => {
    const run = tail.then(job)
    tail = run.catch(() => undefined)

    return run
  }
}

files.hooks/lib/sessions.ts:
import type { LiveSession } from '../../types'

// Every live Claude Code process keeps a registry file, ~/.claude/sessions/<pid>.json:
//   {"pid":31600,"sessionId":"…","name":"jev-router-41","entrypoint":"cli",…}
// A crashed process can leave its file behind, so a row counts only while its
// pid is still running as a Claude Code process (pids are reused). Only what
// the wait banner needs is read: which session, which process, what to call it.

export type SessionFile = { pid: number; sessionId: string; name: string }

const MAX_NAME = 80

export const parseSessionFile = (json: string): SessionFile | undefined => {
  try {
    const value: Record<string, unknown> | null = JSON.parse(json)
    const { pid, sessionId, name } = value ?? {}

    // The pid names a file in the marks folder, so it must be an ordinary process number.
    if (typeof pid !== 'number' || !Number.isInteger(pid) || pid <= 0 || typeof sessionId !== 'string') return undefined

    return { pid, sessionId, name: typeof name === 'string' ? name.slice(0, MAX_NAME) : sessionId.slice(0, 8) }
  } catch {
    return undefined
  }
}

/** The registry files that parse; the rest are skipped. */
export const parseSessionFiles = (texts: readonly string[]): SessionFile[] =>
  texts.flatMap(text => {
    const file = parseSessionFile(text)

    return file === undefined ? [] : [file]
  })

/** The running processes in `tasklist /FO CSV /NH` output, pid to image name: `"claude.exe","31600",…`. */
export const parseTasklist = (csv: string): Map<number, string> =>
  new Map(
    csv.split('\n').flatMap(line => {
      const match = /^"([^"]*)","(\d+)"/.exec(line.trim())

      return match === null ? [] : [[Number(match[2]), match[1] ?? ''] as [number, string]]
    }),
  )

const CLAUDE_IMAGE = /^(claude|node)(\.exe)?$/i

/** The live sessions: those whose pid still runs as Claude Code. A session id appears once. */
export const liveSessions = (
  files: readonly SessionFile[],
  processes: ReadonlyMap<number, string>,
  hereId: string,
): LiveSession[] => {
  const isAlive = (file: SessionFile): boolean => CLAUDE_IMAGE.test(processes.get(file.pid) ?? '')
  const rows = files
    .filter(isAlive)
    .map<LiveSession>(file => ({ id: file.sessionId, pid: file.pid, name: file.name, isHere: file.sessionId === hereId }))

  return [...new Map(rows.map(row => [row.id, row])).values()]
}

const REGISTRY_DIR = '.claude/sessions'

/** The reads the registry needs; the caller hands them in so this stays free of `$`. */
export type SessionIo = {
  list: (dir: string) => Promise<readonly { name: string; size: number; mtimeMs: number; kind: string; isLink: boolean }[]>
  /** A file's text; empty when it cannot be read. */
  read: (path: string) => Promise<string>
  /** The process table, as `tasklist /FO CSV /NH` prints it. */
  tasklist: () => Promise<{ exitCode: number; stdout: string }>
}

/** At most this many registry files are read, the newest; and none over this many bytes (a real one is a few hundred). */
const MAX_FILES = 32
const MAX_FILE_BYTES = 65_536

/** The live sessions out of the registry and the process table; a table that fails rejects. */
export const readLiveSessions = async (home: string, hereId: string, io: SessionIo): Promise<LiveSession[]> => {
  const dir = `${home}/${REGISTRY_DIR}`
  const names = (await io.list(dir))
    .filter(entry => entry.kind === 'file' && !entry.isLink && /^\d+\.json$/.test(entry.name) && entry.size <= MAX_FILE_BYTES)
    .sort((a, b) => b.mtimeMs - a.mtimeMs)
    .slice(0, MAX_FILES)
    .map(entry => entry.name)
  const files = parseSessionFiles(await Promise.all(names.map(name => io.read(`${dir}/${name}`))))
  const table = await io.tasklist()
  if (table.exitCode !== 0) throw new Error(`tasklist exited ${table.exitCode}`)

  return liveSessions(files, parseTasklist(table.stdout), hereId)
}

files.hooks/lib/waiting.ts:
import type { LiveSession, WaitReason, WaitingRow } from '../../types'
import { ago, plain } from './plain'

// Each session keeps one small mark file, named by its pid, saying whether it
// is waiting on the person right now and since when. The session id inside it
// tells a live session's mark from one a reused pid left behind. The format is
// the one status-sidebar writes and reads, so sessions running either see each other.

const MARK_DIR = '.claude/mods-state/status-sidebar/waiting'

/** The mark file of the session running as `pid`. */
export const markPath = (home: string, pid: number): string => `${home}/${MARK_DIR}/${pid}.json`

export const markText = (sessionId: string, reason: WaitReason | null, sinceMs: number): string =>
  JSON.stringify({ sessionId, reason, sinceMs })

const REASONS: readonly string[] = ['permission', 'question']

/** The wait a mark records for `sessionId`; undefined when cleared, broken or another session's. */
export const parseMark = (text: string, sessionId: string): { reason: WaitReason; sinceMs: number } | undefined => {
  try {
    const value: Record<string, unknown> | null = JSON.parse(text)
    const { reason, sinceMs } = value ?? {}

    if (value?.sessionId !== sessionId || typeof reason !== 'string' || !REASONS.includes(reason)) return undefined

    return { reason: reason as WaitReason, sinceMs: typeof sinceMs === 'number' ? sinceMs : 0 }
  } catch {
    return undefined
  }
}

/** The other live sessions waiting on the person, the longest wait first. */
export const waitingRows = (rows: readonly LiveSession[], markOf: (pid: number) => string): WaitingRow[] =>
  rows
    .filter(row => !row.isHere)
    .flatMap(row => {
      const mark = parseMark(markOf(row.pid), row.id)

      return mark === undefined ? [] : [{ id: row.id, name: row.name, ...mark }]
    })
    .sort((a, b) => a.sinceMs - b.sinceMs)

/** The other live sessions waiting on the person: each one's mark file is read (`readFile`; empty when it cannot be). */
export const readWaits = async (
  home: string,
  rows: readonly LiveSession[],
  readFile: (path: string) => Promise<string>,
): Promise<WaitingRow[]> => {
  const marks = new Map(
    await Promise.all(rows.filter(row => !row.isHere).map(async row => [row.pid, await readFile(markPath(home, row.pid))] as const)),
  )

  return waitingRows(rows, pid => marks.get(pid) ?? '')
}

/** True when two reads found the same waits, in the same order. */
export const sameWaits = (a: readonly WaitingRow[], b: readonly WaitingRow[]): boolean =>
  JSON.stringify(a) === JSON.stringify(b)

/** A tool that stops to ask the person: a question, or a plan to approve. */
export const isQuestionTool = (tool: string): boolean => tool === 'AskUserQuestion' || tool === 'ExitPlanMode'

const WAIT_LABEL: Record<WaitReason, string> = { permission: 'permission', question: 'question' }

/**
 * The banner line: the session that has waited longest, why, and since when,
 * with how many more wait. Undefined while nobody does. Permission waits are
 * known to start and not to end until their call returns, hence "waiting on you".
 */
export const bannerText = (rows: readonly WaitingRow[], nowMs: number): string | undefined => {
  const [first] = rows
  if (first === undefined) return undefined

  const more = rows.length > 1 ? ` · +${rows.length - 1} more` : ''

  return `! waiting on you: ${plain(first.name)} ${WAIT_LABEL[first.reason]} ${ago(first.sinceMs, nowMs)}${more}`
}

