      "title": "Dock width",
      "description": "Share of the terminal width the pane takes when docked in fullscreen (/tui fullscreen), 20-80; follows the terminal when it is resized. A width you dragged the dock to wins",
      "type": "number",
      "default": 40
    },
    "maxCards": {
      "title": "Cards before swimlanes",
      "description": "Agent cards drawn side by side; more agents than this switch to swimlanes (1-6)",
      "type": "number",
      "default": 3
    },
    "layout": {
      "title": "Layout",
      "description": "auto: a summary of at most 8 rows when the pane sits inline above the prompt, two columns from 110 columns when docked, one column otherwise",
      "type": "string",
      "options": [
        "auto",
        "compact",
        "wide",
        "mini"
      ],
      "default": "auto"
    },
    "palette": {
      "title": "Palette",
      "description": "theme follows your Claude Code theme (light, dark, colour-blind); pastel is fixed colours tuned for dark terminals",
      "type": "string",
      "options": [
        "theme",
        "pastel"
      ],
      "default": "theme"
    },
    "openOnStart": {
      "title": "Open on start",
      "description": "Open the pane when a session starts",
      "type": "boolean",
      "default": true
    },
    "statusLine": {
      "title": "Status line",
      "description": "Show context, agents, consults and denials in the status line",
      "type": "boolean",
      "default": true
    }
  }
}

files.types/index.d.ts:
export type Moment = 'before a plan' | 'error repeats' | 'before done'

export type Bucket = 'file' | 'shell' | 'other'

/** rule: settings allowed it. ask: put to the decider, outcome pending. cleared: asked, then ran. deny: refused. */
export type Verdict = 'rule' | 'ask' | 'cleared' | 'deny'

export type Main = {
  model: string
  effort: string
  mode: string
  steps: number
  isRunning: boolean
}

export type Usage = {
  pct: number | null
  tokens: number | null
  window: number
  /** `resetsAt`: when the window resets, in ms since the epoch; null when the API gave no time,
   *  absent in state saved before it was kept. */
  limits: { kind: string; pct: number; resetsAt?: number | null }[]
  compactions: number
  lastCompactAt: number | null
}

export type Consult = { id: string; at: number; endAt: number | null; moment: Moment; via: string }

export type Architect = { consults: Consult[]; ids: string[]; seen: string[]; lastAdvice: string }

export type Check = {
  id: string
  tool: string
  bucket: Bucket
  verdict: Verdict
  inSubagent: boolean
  detail: string
  at: number
}

export type Tally = { rule: number; ask: number; cleared: number; deny: number }

export type Gate = { recent: Check[]; totals: Record<Bucket, Tally> }

export type ToolNote = { tool: string; text: string; isError: boolean }

export type AgentCard = {
  id: string
  type: string
  model: string
  /** The effort of its latest step, as the main box says it (`high`, or a number); empty when it has none. */
  effort: string
  description: string
  status: string
  spawnedAt: number
  endedAt: number | null
  /** The agent's context now: input + cache read + cache write of its latest step. */
  ctx: number
  /** Output tokens summed over its steps. */
  out: number
  steps: number
  lastStop: string | null
  tools: ToolNote[]
  answer: string
  /** Set on a `codex exec` run the main session started, shown as a subagent; its id is the shell call's. */
  codex?: { taskId?: string }
}

/** A model loop whose id matches no card: a workflow agent, a compaction or a memory fork. */
export type Loop = { id: string; steps: number; firstAt: number; lastAt: number; isDone: boolean }

export type LogLine = {
  at: number
  who: string
  text: string
  agentId: string | null
  kind: 'info' | 'error' | 'consult' | 'done'
}

export type Turn = {
  edits: number
  errorStreak: number
  errors: number
  isReviewing: boolean
  startedAt: number
}

export type Receipt = {
  durationMs: number
  agents: number
  edits: number
  errors: number
  reason: string
}

export type Layout = 'auto' | 'compact' | 'wide' | 'mini'

/** `gitOpen`: the 分支 panel's list of unreviewed paths is unfolded (hotkey u). */
export type View = { expanded: string | null; gateOpen: Bucket | null; layout: Layout | null; gitOpen: boolean }

export type Roster = { architectTypes: string[] }

/** A usage window as last reported: how much of it is used, and when it resets (ms since the epoch). */
export type UsageWindow = { usedPercent: number; resetsAtMs?: number }

/** Codex's model and effort are what its config selects (display only); the windows come from its newest rollout. */
export type CodexQuota = {
  model?: string
  effort?: string
  fiveHour?: UsageWindow
  weekly?: UsageWindow
  /** Why the figures are missing, when they are. */
  note?: string
  /** When the windows were reported: the server answer's time, or the rollout event's; absent when unknown. */
  readAtMs?: number
  /** When the server last answered a refresh the person asked for. */
  serverAtMs?: number
}

/** The Fable weekly window from /api/oauth/usage; `isStale` when the last ask failed and the figure may be old. */
export type FableQuota = { window?: UsageWindow; isStale: boolean }

export type WaitReason = 'permission' | 'question'

/** Another live session waiting on the person; the longest wait is first in a list of them. */
export type WaitingRow = { id: string; name: string; reason: WaitReason; sinceMs: number }

/** A Claude Code process the session registry lists and the process table confirms. */
export type LiveSession = {
  id: string
  /** The process it runs in, which names its wait mark. */
  pid: number
  name: string
  /** True for the session this dashboard belongs to. */
  isHere: boolean
}

/** The session's repository as the 分支 panel shows it. */
export type GitSnap = {
  branch: string
  /** The branch it tracks (`origin/main`); absent with no upstream. */
  upstream?: string
  /** Commits not pushed / not pulled; absent with no upstream. */
  ahead?: number
  behind?: number
  /** Files that differ from HEAD, untracked ones included. */
  changed: number
  /** Of those, the ones whose content no review has seen; absent (unknown) when the content hashes or the review record could not be had. */
  unreviewed?: number
  /** Their paths, relative to the root, the first UNREVIEWED_SHOWN of them. */
  unreviewedPaths: string[]
}

declare module 'claude-code' {
  interface PluginState {
    'cc-dashboard': {
      meta: { schemaVersion: number }
      main: Main
      usage: Usage
      architect: Architect
      gate: Gate
      agents: AgentCard[]
      loops: Loop[]
      log: LogLine[]
      turn: Turn
      receipt: Receipt | null
      view: View
      roster: Roster
      /** Codex's usage windows; null until read, or where Codex cannot be read (no USERPROFILE or SystemRoot). */
      codex: CodexQuota | null
      /** The session's repository; null outside one, or when git cannot be read. */
      git: GitSnap | null
      /** The Fable weekly window; null until first asked. */
      fable: FableQuota | null
      /** This session's own wait on the person, null when there is none. */
      waiting: { reason: WaitReason; sinceMs: number } | null
      /** The live Claude Code sessions, from the registry and the process table. */
      sessions: LiveSession[]
      /** The other live sessions waiting on the person, longest wait first. */
      waitingOthers: WaitingRow[]
    }
  }
}
